Method.Source:
/// <summary>
/// PaffH 24.04.21
/// get singleton of NDXModelNumberHandler
/// </summary>
/// <param name = "initialize">boolean</param>
/// <returns>instance of NDXModelNumberHandler</returns>
public static NDXModelNumberHandler instance(boolean initialize = false)
{
    NDXModelNumberHandler nDXModelNumberHandler;

    SysGlobalCache globalCache = appl.globalCache();
    if (!initialize && globalCache.isSet(classStr(NDXModelNumberHandler), 0))
    {
        nDXModelNumberHandler = globalCache.get(classStr(NDXModelNumberHandler), 0);
    }
    else
    {
        nDXModelNumberHandler = new NDXModelNumberHandler();
        appl.globalCache().set(classStr(NDXModelNumberHandler), 0, nDXModelNumberHandler);
    }
    return nDXModelNumberHandler;
}

	/// <summary>
    /// PaffH 24.04.21
    /// </summary>
    /// <returns>NDXModelNumberHandler</returns>
    public static NDXModelNumberHandler construct()
    {
        return new NDXModelNumberHandler();
    }

/// <summary>
/// PaffH 24.04.21
/// </summary>
/// <param name = "_NDXModelNumber">NDXModelNumber</param>
/// <returns>NDXModelNumber</returns>
public NDXModelNumber parmNDXModelNumber(NDXModelNumber _NDXModelNumber = NDXModelNumber)
{
    nDXModelNumber = _NDXModelNumber;
    return nDXModelNumber;
}

    /// <summary>
    /// PaffH 29.04.21
    /// productnumber = NDXModelNumber
    /// </summary>
    /// <param name = "_productNumber">ProductNumber</param>
    /// <param name = "_nDXItemIdHandler">NDXItemIdHandler</param>
    /// <returns>NDXModelNumber</returns>
    public NDXModelNumber nDXModelNumberFromProductNumber(ProductNumber _productNumber, 
		NDXItemIdHandler _nDXItemIdHandler = NDXItemIdHandler::constructFromDataAreaId())
    {
        nDXModelNumber = _nDXItemIdHandler.checkNDXModelNumber(_productNumber);
        return nDXModelNumber;
    }

/// <summary>
/// PaffH 29.04.21
/// prefix ("1-", "2-" ... must be truncated from itemid to get the NDXModelnumber
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_nDXItemIdHandler">NDXItemIdHandler</param>
/// <returns>NDXModelNumber</returns>
public NDXModelNumber nDXModelNumberFromItemId(ItemId _itemId,
    NDXItemIdHandler _nDXItemIdHandler = NDXItemIdHandler::constructFromDataAreaId())
{
    return this.nDXModelNumberFromProductNumber(_itemId, _nDXItemIdHandler);
}

	/// <summary>
    /// PaffH 29.04.21
    /// check: is itemId prefixed with company-id
    /// </summary>
    /// <param name = "_itemid">ItemId</param>
    /// <returns>container</returns>
	public container itemIdHasCompanyPrefix(ItemId _itemid)
    {
        NDXHelperRegex regex = new NDXHelperRegex();
        container conRet = regex.getMatches('^[0-9]-.*', _itemid);

        return [conLen(conRet) > 0, conRet];
    }
